item.content:encoded:
body{
	font-size:0.9375rem !important;	
}
.elementor-2 .elementor-element.elementor-element-7cfb7af .elementor-heading-title,.elementor-widget-heading .elementor-heading-title{
	font-family:"Open Sans", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen-Sans, Ubuntu, Cantarell, "Helvetica Neue", sans-serif !important;
}
h1.entry-title{
	font-size: 2.375rem;
	color: #3272e3;
}
h1, h2, h3, h4{
	color:#233060 !important;
}
h4 strong{
  font-size: 1.25rem;
  line-height: 1.5;
	color:#233060;
}
#counterBgWrap{
	margin:0;
	box-sizing:content-box;
}
a.removeCkBtn{
	box-sizing:content-box;
}
a.removeCkBtn:hover {
  color:#fff;
}
strong{
	font-size:1rem !important;
	color:#233060 !important;
}

stickynav {
  background:#ffff;
  height:70px;
  z-index:999;
  margin:0 auto;
  border-bottom:1px solid #dadada;
  width:100%;
  position:fixed;
  top:0;
  left:0;
  right:0;

}
#stickynav{
	min-height: 135px;
	position: sticky;
	background: #fff;
	top: 30px;
	padding: 20px 0;
	margin: 0;
}
.ckTipBtn,.ckTipText{
	margin:0;
}
.wp-pro-item{
	height:100%;
}
.wp-pro-item .elementor-widget-container{
	height:100%;
}
.copyright_left p{
	margin:0;
}
.cookiesTip, .copyrightDiv{
	font-size: 14px;
}
